D = {}

D['makonde-lipiko-mask'] = ("The lipiko is the carved wooden mask of the Makonde people of northern Mozambique, worn by male dancers in the mapiko, a masked dance that forms part of the likumbi initiation rite marking the passage from puberty to adulthood. The mapiko performance, which UNESCO inscribed on its List of Intangible Cultural Heritage in Need of Urgent Safeguarding in 2023 under the name Ingoma ya Mapiko, takes place in an open enclosure, often beneath mango trees, with dancers, drummers and a choir of men and women facing each other. The dancer's whole body is covered by the costume, and the mask, carved from a single block of wood and sometimes from scrap metal such as old cooking pots, shows a stylized face with pronounced lips and painted details, and is kept hidden from the uninitiated. Within the rite the masked dancer is held to embody the spirit of a dead ancestor, and the dance both solemnly stages the world of the dead and entertains the living, since it may also be danced at funerals of group members and for general celebration. Young Makonde men learn the making and wearing of masks and the steps of the dance during the secret initiation camp, with the knowledge passed down from elder carvers to the initiates.")
D['moroccan-tagine'] = ("The tagine is the conical clay cooking vessel of Morocco and the wider Maghreb, which gives its name to the slow-braised stews that are cooked and served in it. Its tall, dome-shaped lid traps rising steam, which condenses and drips back onto the food, so the dish cooks in a small amount of liquid over embers or a low flame without much oil or added water. Traditional tagines are hand-thrown from terracotta and may be left unglazed or covered with a decorative glaze, and the glazed base of the pot is carried to the table with the conical lid still in place. The Arabic name tajin is used for both the pot and the food, and although the dish's precise history is debated, the Amazigh population of North Africa is generally credited with developing the slow-simmering vessel, while early cookery books from the medieval Islamic world already attest to similar stews. Because a well-made tagine can be cooked over a simple brazier of charcoal, it remains an everyday utensil in mountain villages and urban kitchens alike, served family-style with bread used for dipping.")
D['burnous-cloak'] = ("The burnous is the hooded, floor-length cloak of the Maghreb, worn by Amazigh (Berber) and Arab men across Morocco, Algeria, Tunisia and Libya. It is woven in one seamless piece from pure sheep's wool, often left in the natural cream or brown colour of the fleece or dyed, and it is fitted with a single pointed hood that can be drawn over the head in sun, wind or rain. In pre-modern times the burnous served as overcoat, blanket and sleeping bag for travellers and shepherds on the steppe, while a white burnous became the ceremonial dress of chiefs, religious leaders and notables, handed down as an honour and worn at weddings, feasts and festivals. The garment is also remembered in legend, since tribal saints and warriors are described in oral tradition as being wrapped in or given a burnous as a mark of protection and blessing. Today the burnous is worn mainly on formal occasions, but it remains a defining element of Maghrebi identity and appears in the national dress of several North African countries.")
D['tizerzai-brooch'] = ("The tizerzai is a large silver fibula brooch of the Amazigh (Berber) peoples of Morocco and Algeria, traditionally worn in pairs at the shoulders to fasten the tasseled woollen wraps and tunics of women. Triangular or delta-shaped, each brooch fastens with a long pin and is often richly worked with granulation, filigree, enamel and inset glass or coral, so that the clasp of a garment becomes a display of a family's wealth and craft. Ethnographic collections, including those documented by the French artist Jean Besancenot in his 1942 Costumes du Maroc, record pairs of tizerzai worn by dancers and brides in southern and Atlas communities, with some examples reaching more than a metre in length when the connecting chains are counted. In Amazigh tradition the ornaments protect the wearer from the evil eye and declare her social standing, and they are passed from mother to daughter along with the rules of how they should be worn. Because the fibula's shape is echoed in the triangular motifs of Amazigh weaving and tattooing, the tizerzai is today read as a marker of indigenous North African identity.")
D['kabyle-earthenware'] = ("Kabyle earthenware is the red-clay pottery of the Great Kabylia mountains of northern Algeria, a craft kept almost exclusively in the hands of women. The pots are built by hand from coils of local clay, without a wheel, then burnished with a pebble while still damp and painted before firing with geometric patterns in black, beige and red. The repertoire includes water jars, storage pots, and wide platters used to serve couscous at weddings and other feasts, and the interior of each piece is divided into circles, checkerboards, crosses and triangles that radiate from the centre. These motifs are named and read by the women who make them, and they are believed to carry meanings of supernatural protection and fertility, some of which are shared with the diamond patterns of Amazigh weaving, jewellery and facial tattoos. Because the recipes for clay, paints and firing are handed down from mother to daughter, each pot carries the imprint of a lineage, though the regional styles differ from village to village across the massif.")
D['chaoui-aures-kilim'] = ("The Chaoui kilim is a flat-woven woollen rug made by the Chaoui Amazigh women of the Aures mountains in eastern Algeria. Because the Aures is a cold, high country of oak forests and steppe, the weavers use the fleece of the local sheep to create blankets, saddle cloths, tent curtains and floor rugs, working on a horizontal ground loom that can be set up and dismantled as families move between seasonal pastures. The weaving is warp-faced, so that the geometric design is visible on both faces, and the patterns of diamonds, ladders, zigzags and small protective 'eye' motifs are handed down within each family rather than copied from books. Dyes traditionally came from madder roots, walnut husks, indigo and other plants gathered in the mountains, giving a palette of warm reds, browns and indigo against undyed cream wool. Like other Amazigh textiles, the Aures kilim carried apotropaic meaning, with border motifs believed to turn aside the evil eye, and today these rugs are also valued by collectors as documents of Chaoui identity.")
D['tunisian-chechia'] = ("The chechia is the traditional red felt cap of Tunisia, worn by men since the early modern period and regarded as a national emblem of the country. Its production was long a chain of specialized workshops: wool was combed, spun and knitted into a raw cap, then fulled with water and heat at sites such as El Battan on the Medjerda river, dyed crimson with madder or similar dyes, and finally stretched and finished over wooden moulds in Tunis. The craft flourished with the arrival of Andalusian Morisco artisans at the start of the 17th century, and their guild became so influential that a whole quarter of the medina of Tunis, the Souk Ech-Chaouachine, was built in 1691-92 for the trade of the so-called chaouachis. A single chechia could take about two months to pass through the hands of these workshops, and the finished caps were exported across North and West Africa and even to Europe. Worn for prayer, for feasts and weddings, and formerly as part of daily dress under the turban, the chechia is distinct from the Ottoman fez and remains a living symbol of Tunisian identity.")
D['gourgui-water-jar'] = ("The gourgui is a large earthenware water jar of Tunisia, made of porous red terracotta and fitted with a narrow neck and a pouring spout, traditionally used to store and cool drinking water. Because water slowly seeps through the unglazed clay and evaporates from the surface, the contents of the gourgui stay noticeably cooler than the air in the hot Tunisian summer. The jar was kept in the skifa, the entrance hall of traditional houses, mounted on a wooden stand formed of three crossed branches and a crescent-shaped tray, where it greeted family and guests alike, and similar jars still stand in the courtyards of mosques and in front of shops for passers-by and travellers. Before piped water, the gourgui supplied both daily drinking water and water for the ritual ablutions of Islam, and it was produced in three sizes, large, medium and small, in the pottery-making towns of the country. Though plastic and refrigerators have replaced it in most homes, the gourgui is still remembered as a symbol of hospitality and of Tunisian craft.")
D['garamantian-chariot'] = ("The Garamantian chariot is the two-wheeled horse-drawn vehicle represented in the rock art of the Libyan Sahara, above all in the massif of the Tadrart Acacus, which was listed as a UNESCO World Heritage site in 1985. The engravings, often showing the horse at a stylized 'flying gallop', belong to the Horse Period of Saharan rock art and are attributed to the Garamantes, the desert people whose kingdom in the Fezzan and capital at Garama are confirmed by archaeology and by the classical writers. Herodotus describes the Garamantes driving four-horse chariots into the desert to hunt the 'Troglodyte Ethiopians', and hundreds of similar chariot drawings are scattered across the Sahara from Libya to the Atlantic, along the ancient routes of the trans-Saharan trade. These images record the arrival of the horse as a prestige and military animal in the region around the first millennium BCE, even if long-distance chariot travel in the deep desert is now doubted by scholars. The chariot pictures of the Acacus survive as the clearest visual testimony of the Garamantian world, the same world that built an underground network of foggaras to irrigate the desert farms.")
D['canopic-jar'] = ("Canopic jars are the four vessels in which ancient Egyptian embalmers placed the organs removed from the body during mummification, the liver, lungs, stomach and intestines being preserved separately so that the deceased could use them again in the afterlife. The jars, made of alabaster, limestone, wood or pottery, stood in the tomb chest beside the coffin, and by late times each lid was carved as the head of one of the Four Sons of Horus, the protective genii Imsety, Hapy, Duamutef and Qebehsenuef. Spell 151 of the Book of the Dead invokes these guardians, and the whole procedure was overseen by Anubis, the jackal-headed god of embalming who is said to have invented mummification when he treated the body of Osiris. The practice of preserving the viscera is attested from the Old Kingdom onward and illustrates the Egyptians' conviction that the body must remain intact for the next life. Excavated canopic sets, with their carved lids and painted texts, are among the most recognizable objects of the Egyptian burial assemblage.", {'featured_in_stories': ['anubis-story']})
D['egyptian-kohl-tube'] = ("The kohl tube is a small cylindrical vessel used in ancient Egypt to hold kohl, the black and green eye paint worn by men and women from the Old Kingdom onward. Eye paint was prepared by grinding minerals on a slate palette and mixing the powder with fat, then applying it around the eyes with a stick; green paint from malachite was mainly cosmetic, while black paint from galena protected the eyes from the glare of the sun and, because of its lead content, repelled flies and bacteria that could cause eye disease. Kohl was so valued that the ancient Egyptians ranked it second only to water as a preventive of disease, and tubes were made from wood, faience and glass, often with a small applicator stick and a pin at the base. Some New Kingdom tubes, especially from the Ramesside period of the 13th to 11th centuries BCE, were decorated with the figure of the dwarf god Bes, whose fearsome image was invoked to drive away the supernatural forces believed to cause eye infections. The word kohl itself, of Arabic origin, later spread across the Islamic world for the same dark cosmetic used to line the eyes.", {'related_creatures': ['bes']})
D['sudanese-kaskara'] = ("The kaskara is the straight, double-edged broadsword of Sudan and the neighbouring regions of Chad and Eritrea, with a long blade, a cruciform quillon guard and a flattened disc pommel. Although most surviving examples date from the 19th century, the type is thought to have appeared around the 14th century and to preserve the straight-bladed style of the medieval Arab sword. The kaskara was an essential possession of most men across the central and eastern Sudan, from Chad through Darfur to the Red Sea coast, and it was worn horizontally across the back or between the upper arm and the chest. Some fine examples combine locally made Sudanese hilts with imported blades, as with a sword in the Met Museum whose Iranian watered-steel blade bears the name of Nasir al-Din Shah Qajar and which was taken as booty at the battle of Omdurman in 1898. Beyond its warrior use, the kaskara served in dances, oaths and ceremonies, and as a badge of manhood and honour among the peoples of the Nile and the Sahara.")
D['sudanese-girba'] = ("The girba is the traditional water-skin of Sudan, made from the whole hide of a goat turned inside out so that the sealed legs hang as a bag while the neck serves as the opening for filling and pouring. The soft leather container is carried over the shoulder or slung on a donkey, and its porous surface slowly lets a thin film of water evaporate, which cools the contents even under the fierce heat of the northern Sudan. Tanning with acacia bark and vegetable juices, and rubbing with oils, keeps the skin supple and waterproof, and a well-kept girba can survive for years, being cleaned, dried and re-oiled between uses. In villages and camps the girba was the everyday vessel for carrying water from the Nile or the well, taking the place that clay jars hold elsewhere, and it shares its design with the Spanish bota bag and other leather flasks of the Mediterranean world. The girba is also a familiar prop in Sudanese folk memory, where hospitality is measured by the cold water poured from it for the weary guest.")
D['vajra-of-indra'] = ("The vajra is the thunderbolt weapon of Indra, the storm god of the Rigveda, and the foremost weapon in early Indian mythography. In the Vedic hymns Indra wields the vajra to strike down the serpent-demon Vritra, who held back the world's waters, and by that blow releases rivers, rain and light; the word itself came to mean both the physical bolt and the diamond, as being unbreakable and irresistible. Later Puranic tradition gives a dramatic origin for the weapon, telling that the sage Dadhichi offered his own bones, from which the divine smiths forged the indestructible thunderbolt with which Indra defeated Vritra. In Hindu iconography the vajra appears as a short metal club with ribbed heads, carried by Indra and sometimes by other deities, while in Vajrayana Buddhism the same name and form were adopted for the ritual scepter held in the right hand during meditation and consecration, paired with a bell. Because of this double life, the vajra spans the worlds of Vedic warfare and Buddhist ritual as a symbol of indestructible truth.")
D['trishula-of-shiva'] = ("The trishula is the three-pronged spear or trident of the Hindu god Shiva, carried in his hand and planted before his shrines, so that the trident has become his most recognizable attribute. The three prongs are traditionally read as the three gunas of sattva, rajas and tamas, or as the triad of creation, preservation and destruction, and the weapon appears as an instrument of both justice and destruction in the myths. In the celebrated tale of the three demon cities, Shiva is said to have burned the demon Tripura and his aerial cities with a single arrow, while in other stories it is the trishula itself that he hurls to punish or to sever. In the two Ganesha legends the trident plays a decisive role, for it is Shiva's trishula that cuts off the head of the boy Ganesha at the door of Parvati's chamber, and the same blow is retold in different words in accounts of Ganesha's origin. The trishula is also carried by Shaiva ascetics, imprinted on offerings, and reproduced in metal as a protective emblem over homes and shrines.", {'featured_in_stories': ['shiva-story', 'ganesha-story', 'the-origin-of-ganeshas-elephant-head']})
D['sudarshana-chakra'] = ("The Sudarshana chakra is the spinning, razor-edged discus of the Hindu god Vishnu, held in his upper right hand together with the conch, mace and lotus in the classic four-armed image. Its name means 'beautiful in form' or 'auspicious disc', and in myth it is the personal weapon that Vishnu casts at enemies, flying to its target and returning to his finger. In the churning of the ocean the chakra is sometimes said to have been the weapon that cut off the head of the demon Svarbhanu, the being who became the ascending and descending nodes Rahu and Ketu when the gods and demons churned for the nectar of immortality. The chakra also appears in the hands of Narasimha, Vishnu's man-lion avatar, who destroyed the demon king Hiranyakashipu and is worshipped together with the discus in temple images. Because the weapon is inseparable from Vishnu, it is a standard element of the temple icon, engraved on stones and invoked in protective prayer, and its recurring presence ties every one of the avatar stories to a single divine wielder.")
D['shiva-lingam'] = ("The lingam is the upright, pillar-like aniconic emblem of the Hindu god Shiva, found in temples, shrines and homes across India and the South Asian diaspora, and worshipped as the formless presence of the god. Its classic shape is a smooth column set in a circular base called the pitha, which represents the yoni of the goddess Shakti, so that the two pieces signify the union of the male and female principles. The foundational legend, the lingodbhava, tells that Shiva revealed himself as an infinite pillar of fire, so vast that neither Brahma nor Vishnu could find its top or bottom. In daily worship the lingam is bathed with water, milk and other offerings while the priest recites mantras, and to step over the lingam is considered a serious offence; certain lingams, the jyotirlingas, are among the most sacred pilgrimage sites of Shaivism. The form is also found as the mukhalinga, carved with Shiva's faces, and as the natural river-worn stones called banalingas, collected by devotees from the Narmada river.")
D['rudraksha-mala'] = ("The rudraksha mala is a string of 108 prayer beads made from the seeds of the rudraksha tree, Elaeocarpus ganitrus, which grows in the Himalayas, the Indo-Malayan region and as far as Southeast Asia. The name means 'Rudra's eye', and the Shiva Purana relates that the rudraksha sprang from the tears that fell from the god Rudra-Shiva's eyes during his long penance, so that the beads are sacred to Shiva and are worn by Shaiva ascetics and householder devotees alike. Each bead is marked with vertical grooves called mukhi, from one to twenty-one, of which the five-faced type is the most common and most auspicious, and the Rudrakshajabala Upanishad gives rules for their wearing and the benefits of each count. The string is used for japa, the repetition of a mantra, and is also worn on the neck, wrist or arm as a guarantee of protection and spiritual merit. Because rudraksha is both a botanical product and a ritual object, it is traded widely, and its beads can be found strung with gold, silver or cotton thread in the markets of Nepal and Varanasi.")
D['ganesh-idol'] = ("The Ganesha idol is the murti or sacred image of Ganesha, the elephant-headed son of Shiva and Parvati, who as the remover of obstacles is invoked at the beginning of every undertaking, from weddings and housewarmings to examinations and journeys. According to the most widely repeated story, Parvati created the boy from the paste with which she bathed and set him to guard her door; when Shiva tried to enter, the boy barred the way, and Shiva struck off his head with his trident. At Parvati's grief the god promised to restore the boy, taking the head of the first living creature he found, an elephant, and this origin is retold in ganesha-story and in the tale of the origin of Ganesha's elephant head. Ganesha idols range from tiny brass household figures to the huge clay and plaster images commissioned for Ganesh Chaturthi in Maharashtra and elsewhere, which are worshipped and then immersed in water at the close of the festival. The idol carries his attributes, including the broken tusk, the modaka sweet and the mouse vehicle, each of which is glossed in sermons and picture books.")
D['diya-oil-lamp'] = ("The diya is the small clay oil lamp of the Indian subcontinent, a shallow bowl of baked earth filled with ghee or oil and fitted with a cotton wick, lit during worship and festivals. Its name comes from the Sanskrit deepa, meaning lamp, and the rows of little lamps called deepavali gave Diwali its name, the 'row of lights' that greets the goddess Lakshmi at the new moon and celebrates the victory of light over darkness. A diya is lit at the evening arti in Hindu homes, placed at the feet of the deities, on doorsteps and on the thresholds of shops, and floated on rivers during the festivals of the goddesses. Although the classic diya is a simple wheel-thrown cup, the same form is made in bronze, brass and silver for permanent use, and temples keep brass lamps with multiple wicks for the daily ceremony. The flame of the diya carries a fixed set of meanings, purity, warmth and the presence of the divine, and to keep a lamp burning through the night is a common vow and act of devotion.")
D['mangal-kalasha'] = ("The mangal-kalasha, also called purna-kalasha, is a metal or clay pot filled with water and topped with fresh mango leaves and a coconut, an indispensable emblem of auspiciousness in Hindu ritual. It stands at the door of homes during weddings and housewarmings, is established at the beginning of pujas, and is brought to receive honoured guests, because the overflowing pot signifies abundance, fertility and the fullness of the home. In practice the leaves and coconut are taken to invite natural and divine energies, and the water in the pot may be treated as the presence of a deity: during rituals a thread is often tied around the neck of the kalasha and mantra recited over it. The kalasha also appears in the story of the churning of the ocean, in which the pot of amrita, the nectar of immortality, was stolen by the demon Rahu, and the pot is a standard motif over temple doors in South India. Because of this layered meaning, the kalasha is one of the most photographed objects of Hindu domestic life, at once a water jar, a greeting and an invocation.")
D['puja-thali'] = ("The puja thali is the round metal tray on which the objects of Hindu home worship are arranged, so that the whole ritual can be performed from a single plate. Typical contents are a small diya (oil lamp), a container of kumkum (vermilion powder), incense sticks in a holder, a bowl of rice, a flower or marigold petals, and a camphor burner, and the plate is carried in the right hand while the flames are waved before the image in the arti. The thali is usually made of brass, bell metal, silver or stainless steel, and it doubles as the everyday plate of an offering: sweets are placed on it and then distributed as prasad. Because the tray is passed around the household, it is often kept on a low wooden stand in the prayer corner, and the pattern on its rim, floral or with a swastika, is itself chosen for auspiciousness. In many families the thali is a wedding gift and heirloom, and a well-kept thali signals both devotion and domestic order.")
D['brass-urli'] = ("The urli is the wide, shallow brass vessel of South India, most often associated with the kitchens and courtyards of Kerala and Tamil Nadu, where it holds water, flowers and floating candles for decoration or worship. Traditional urulis are hammered or spun from brass and bell metal with a flared rim, and in a Malayali home one may stand on the floor of the entrance hall piled with fresh flowers, or be pressed into service as a cooking and storing pot for rice and water. In temples and festivals the urli has a ceremonial role, holding oil for the brass lamps that are floated in it or receiving offerings of fruit and garlands, and the wide bowl is also used as a base into which a tall traditional oil lamp is set. Because brass is durable and easily polished, old urulis are passed down as household treasures, and the vessel appears in Malayali folk memory as a wedding gift, an heirloom and a standard prop of the naturalistic home garden.")
D['tandoor'] = ("The tandoor is the large clay oven of the Indian subcontinent and of Central and Western Asia, a vase-shaped or bell-shaped pit of baked clay, either sunk into the earth or set above it in a brick surround. It is fired with wood or charcoal and reaches temperatures around 480 degrees Celsius, so the walls bake naan and roti flatbreads directly and roast marinated meat and vegetables hung from hooks, the dishes known collectively as tandoori. In the Punjab the oven was a communal institution, with one village tandoor serving many families of bakers, and the tradition remained largely regional until after the 1947 partition, when Punjabi migrants carried tandoori cooking to the restaurants of Delhi and beyond. Archaeological clay ovens of similar form are known from the Indus Valley civilization around the third millennium BCE, and the word tandoor travelled with the cooking technique across Iran and Central Asia into the Horn of Africa. Because the oven seals in moisture and reaches a dry, fierce heat, it gives the flatbreads and skewers cooked in it a distinctive flavour that cannot be reproduced in a normal domestic stove.")
D['sankha-conch'] = ("The sankha is the conch shell blown as a trumpet in Hindu ritual, and the shell is one of the four emblems held by Vishnu, whose own conch, named Panchajanya, was taken by the god from a demon who lived in the sea. In temple worship the sankha is blown at the start of the ceremony, its long low note summoning the devotees and warding off evil, and a smaller shell is used in the daily arti to pour water over the deity. The conch is also one of the chief auspicious objects of the household, printed on calendars and carved above doors, and a shell that spirals to the right, the dakshinavarti type, is prized as a rarity with special protective power. In the stories of Vishnu the conch sounds together with the discus as the signature of the god, and the vishnu-story repeats the pairing of these attributes. Because the natural shell is the matured body of a sea animal, its use in India is now balanced by ritual injunctions about the taking of life, and artificial shells are common in the shops.")
D['veena'] = ("The veena is the principal string instrument of South Indian (Carnatic) music and the emblem of Saraswati, the goddess of learning, who is always depicted holding a veena whose sound is said to be the voice of wisdom itself. The modern concert-instrument form, called the Saraswati veena, has a large resonator of jackwood with a second smaller gourd behind the neck, twenty-four fixed brass frets on the long fingerboard, and seven strings, four melody and three drone; it is plucked with a wire plectrum while the player sits cross-legged on the floor. Because it belongs to the goddess, the veena is also a ritual object, placed on a stand in the prayer room, and the celestial musicians of Hindu mythology, the gandharvas and the kinnaras, are traditionally pictured playing it together with lutes and cymbals. The word vina appears already in the Vedas, though the instrument has changed shape many times over three thousand years, and it gave its name to later instruments such as the sitar. Today the veena remains the classical instrument of the Carnatic stage, taught from childhood and associated with devotion as much as with concert performance.")
D['tabla'] = ("The tabla is the pair of hand drums that accompanies most North Indian (Hindustani) classical music, consisting of a small wooden drum on the right called the dayan, tuned to the tonic, and a larger metal or clay drum on the left called the bayan, which produces the deep bass. The heads of both drums are built in layers of skin with a black patch of iron and flour paste in the centre, the syahi, which lets the player produce the intricate spoken syllables of tabla language, such as dha, dhin and te te. The drums are struck with the fingers and palm, and a master tabla player can mimic speech, imitate the dance steps and end a composition with a ringing roll. The invention of the instrument is sometimes attributed to the 13th-century poet-musician Amir Khusrau, who is said to have split the older barrel drum, the pakhawaj, in two, and the story is still told in music schools, though scholars now treat it as legend. From court performance to kirtan, ghazal and film, the tabla has become the percussion voice of North Indian music worldwide.")
D['tulwar'] = ("The tulwar is the classic curved sabre of the Indian subcontinent, with a single cutting edge, a shallowly curved blade and a distinctive hilt capped by a disc pommel with a pierced tang button. The hilt, with its broad, flanged guard and long grip, gives the sword an unusually well-balanced feel, and tulwars were carried by Rajput, Maratha and Mughal horsemen for centuries, from the late medieval period through the wars of the 18th and 19th centuries. Blade steel was often made locally or imported from Persia, and many surviving tulwars preserve fine watered-steel blades with armourers' marks, while ornamental examples are damascened with gold lines. The sword also functioned as a social marker: a warrior's tulwar was honoured, taken on campaign, carried on his person at court and given as a reward for valour, and old tulwars frequently carry inscriptions naming their owners. Museums now catalogue these sabres as the standard sidearm of Indian cavalry, and the tulwar's design influenced the swords carried by British army units in India.")
D['katar'] = ("The katar is the Indian punch dagger, a straight, usually double-edged blade set between two parallel side bars that form an H-shaped grip, the whole weapon being pushed forward with the fist like a punch. Because the palm push concentrates the whole force of the arm behind a single point, the katar could pierce mail and helmets in close combat, and it became the characteristic weapon of Rajput and Maratha warriors from about the 16th century onward. In addition to the plain fighting blade there were katar with wavy edges, double blades and side blades, and the wealthiest owners carried gold-damascened pieces with jewelled hilts that were as much jewellery as arms. The katar was also a ceremonial object, presented as a token of loyalty or reward and displayed in processions, and a small katar could be carried concealed in the waistband. Because it is unique to South Asia, the katar is one of the most discussed Indian weapons in the history of arms and armour.")
D['khanda'] = ("The khanda is the broad, straight, double-edged sword of the Indian subcontinent, heavier and stiffer than the curved tulwar, and it is principally associated with the Sikhs of the Punjab and with the Marathas of western India. In Sikh tradition the khanda is the emblem of the Khalsa, the community of initiated Sikhs, and the central motif of the Nishan Sahib, the tall flag of a gurdwara, which shows a double-edged khanda with a chakkar (discus) and two kirpans arranged around it. The sword was carried as a weapon of war in the 17th and 18th centuries and remains a ceremonial and ritual object, used at the initiation ceremony of Amrit, where the sacred syrup is stirred with a khanda, and kept in reverence in Sikh homes and temples. Because the double edge and straight blade allowed a powerful, chopping stroke, the khanda was well suited to the tested cavalry work of the Sikh and Maratha armies. The same term is used in Sanskrit and Hindi for any large sword, so the object carries a long martial lineage beyond the Sikh faith.")
D['kirpan'] = ("The kirpan is the curved sword or dagger that an initiated Sikh wears as one of the five Ks, the panj kakkar, along with unshorn hair (kesh), a comb (kanga), a steel bangle (kara) and the cotton undergarment (kachera). Introduced at the founding of the Khalsa in 1699 by Guru Gobind Singh, the kirpan embodies the Sikh duty to defend the weak and to stand against injustice, and it is worn constantly as a reminder of that responsibility. The size and form of the kirpan vary with the community and the wearer's circumstances, from a small symbolically worn blade in parts of the diaspora to the long ceremonial kirpan of Amritdhari Sikhs, and it is treated not as an offensive weapon but as a sacred article of faith. In Sikh scripture and hagiography the kirpan is praised as the protector of the oppressed, and the five Ks together mark the body of a Sikh as the visible form of the faith. Legal accommodations for the kirpan exist in several countries, and the practice remains an active case study in religious freedom law.")
D['kada-bangle'] = ("The kada, also spelled kara, is the unadorned steel or iron bangle worn by Sikhs on the right wrist, one of the five Ks prescribed at the founding of the Khalsa in 1699. Because it is a closed circle without beginning or end, the bangle is understood as a reminder that God is eternal and without form, and its touch on the wrist constantly recalls the wearer to righteous conduct and restraint. The plain steel of the traditional kada contrasts with the gold ornaments worn by many Hindus and Muslims, signalling that a Sikh should live simply and without attachment to display. In the Punjab the broad steel kada is also worn by non-Sikhs as an item of dress, and in combat the heavy circular bangle could be used as a guard and a blunt knuckle-weapon. The kada is one of the most visible articles of Sikh identity, worn in the workplace, in court and at the gurdwara.")
D['mangalsutra'] = ("The mangalsutra is the necklace that marks a Hindu woman as married, tied around her neck by the groom during the wedding ceremony and then worn for life, though widows set it aside. The name means 'auspicious thread', and the simple gold and black-bead ornament of the north differs from the heavier gold pendant called thali worn in the south, where the tying ceremony is called mangalyam and is the most solemn moment of the wedding. The black beads are traditionally believed to protect the wearer and her husband's family from the evil eye, while the gold signals prosperity, and the number of knots parallels the vows exchanged during the rites. Because the mangalsutra is the visible sign of the married state, its presence or absence is read at once by the whole community, and it is never worn casually. In modern India the ornament has also become a fashion item, with contemporary designs keeping the two beads in silver or diamond settings.")
D['banarasi-sari'] = ("The Banarasi sari is the handwoven silk sari of Varanasi (Banaras) in Uttar Pradesh, famous for its rich brocade, its gold and silver zari, and its intricate pictorial motifs, among them the jangla (vine), bel (creeper), kalga and jal patterns. The weaving tradition grew under the patronage of the Mughal court, which encouraged Persian-inspired floral and arabesque designs in silk and metal thread, and the craft produced the heavy, opulent fabric called kinkhab, woven with real gold thread. A Banarasi sari is woven on a manually operated pit loom, and a single elaborate piece can take weeks or months of work by a karigar, the brocade being built up in fine threads on the wrong side of the cloth. The sari is the classic bridal costume of the region, worn as a symbol of marriage and prosperity, and its silk is still produced in the workshops of the old city, though zari is now often of silver or imitation. In 2009 the Banarasi sari received a Geographical Indication tag, protecting the name for genuine Varanasi work.")
D['phulkari'] = ("Phulkari is the traditional embroidery of the Punjab, in which coarse, hand-spun cotton cloth called khaddar is covered with silk stitches worked from the back in a simple darn stitch to form flowers, diamonds and glowing fields of colour. The name means 'flower work', and the craft is credited to the women of the Sikh and Hindu farming communities of the region, where it has been practiced since about the 15th century. A single piece is worked by hand and can take months; a shawl embroidered over its whole surface is called a bagh, a garden, and it is given as a wedding gift, with the deepest reds reserved for the bride and the most complex pieces started at a child's birth. The motifs show the world of the village, wheat stems, grain and the glitter of sun and mirrors, and each motif has a local name passed down from mother to daughter. Phulkari remains an emblem of Punjabi identity, worn at weddings and festivals and revived in contemporary fashion.")
D['pashmina-shawl'] = ("The pashmina shawl is the fine, handwoven woollen shawl of Kashmir, made from the downy underfleece of the Changthangi goat that grazes the high plateaus of Ladakh and western Tibet. The word pashmina derives from pashm, Persian for the softest animal fibre, and the cleaned wool, only about fifteen microns thick, is spun by hand and woven on a handloom in Srinagar and the valley workshops, a craft that has produced some of the world's most expensive cloth. The shawl was already a luxury good at the courts of the Mughals, who wore and commissioned them, and Kashmiri weaving of fine wool was further stimulated from the 15th century by the arrival of craftsmen and by royal patronage. European taste for the shawl boomed in the 19th century, when Napoleon is said to have presented pashminas to Josephine, and European weavers tried for decades to imitate the Kashmir workmanship. Today genuine pashmina is protected by a Geographical Indication, and shawls are often embroidered with the fine needlework of the valley, though the name is widely copied in blended fabrics.")
D['sacred-tooth-relic'] = ("The Sacred Tooth Relic is the most venerated object in Sri Lankan Buddhism, a tooth believed to be the left upper eye-tooth of the historical Buddha, brought to the island in the 4th century CE by Prince Danta and Princess Hemamala, who is said to have hidden it in her hair. The story of its journey from Dantapura in India is told in the Pali chronicle Dathavamsa, the Chronicle of the Tooth Relic, and the later chapters of the Mahavamsa trace its movement from the first capital, Anuradhapura, through the later capitals Polonnaruwa and Dambadeniya until it reached Kandy. In Kandy the relic is enshrined in the Temple of the Sacred Tooth (Sri Dalada Maligawa), and each summer it is honoured in the great Esala Perahera, a torchlit procession of elephants, dancers and drummers that is among the most spectacular festivals in Asia. The relic functioned politically as well as religiously, since the monarch who guarded it was held to legitimate his rule over the island, and a king who lost the tooth lost his claim to the country. Because the relic is regarded as the presence of the Buddha himself, it is displayed only rarely, and its inner shrine is kept under the most stringent guard.")
D['kandyan-crown'] = ("The Kandyan crown is the royal crown of the Kandyan kingdom of Sri Lanka, the last independent Sinhalese state, which fell to the British in 1815. The crown, of gold richly set with rubies, sapphires and other gems, was worn by the kings of Kandy at great coronation ceremonies and processions, and it carried the whole sovereignty of the kingdom, so that possession of the crown was taken to mean possession of the realm. When the Kandyan chiefs signed the Kandyan Convention of 1815, the regalia, including the crown and the throne, was handed to the British and sent to England, and tradition records memorials of the crown at Windsor Castle, where the regalia long remained. In Sri Lankan memory the loss of the crown is bound up with legend: omens, the fall of a star and other portents are said to have accompanied its removal, and the crown is still popularly spoken of as the sign of a sovereignty that was not handed back. Today the Kandyan crown is remembered through replicas and regalia kept in museums, and the original remains the subject of scholarly dispute between the United Kingdom and Sri Lanka.")
D['kastane-sword'] = ("The kastane is the traditional ceremonial sword of the Kandyan kingdom of Sri Lanka, worn at court as a mark of office and carried in procession, and it is one of the most characteristic creations of Sinhalese metalwork. Its signature feature is the hilt, whose pommel is carved as the head of a lion, the symbol of the Sinhalese people, often in ivory, horn or silver, with the guard and quillons finished with makara heads and scrollwork; the blade itself was frequently a European hanger or cuttoe blade imported by the Dutch and riveted into the local hilt. The kastane was not primarily a battlefield weapon but a dress sword, the attribute of chiefs, princes and royal officials, and it also entered the world of Sinhalese ritual, being used in the masked devil dances and exorcism rites in which the sanni demons and Gara Yakka are invoked. In those rituals the flashing blade is used to dominate the demons and sweep away the evil they represent, linking the courtly sword to the folk religion of the low country. Museums classify the kastane among the finest of Sri Lankan arms, and modern reproductions still accompany Kandyan dancers and drummers.")
D['alms-bowl-relic'] = ("The alms-bowl relic is the bowl that the Buddha is said to have used for his daily begging round, which became a sacred object after his death together with his tooth, his staff and other personal belongings. According to a well-known legend recorded in Gandharan art and later Buddhist texts, after the enlightenment four guardian kings, the lokapalas, each offered the Buddha a stone bowl, and the Buddha miraculously fused the four into one, so that he had a single vessel of modest size for his food. Monks of the Theravada tradition still beg with an alms bowl, holding it in both hands while householders place food in it, and the bowl is for a monk one of his few possessions, a reminder of simplicity and of the gift of the laity. In various Buddhist countries the alms bowl of the Buddha was claimed as a relic by rival pilgrim sites, and the Chinese tradition asserts that the original bowl was carried to China, where it was long venerated. For the believer the bowl embodies the Buddha's poverty and his dependence on the generous, and its veneration is part of the cult of the relics.")

# apply
data = json.load(open(path_in, encoding='utf-8'))
errors = []
for it in data:
    slug = it['slug']
    if slug not in D:
        errors.append('NO ENTRY for ' + slug)
        continue
    val = D[slug]
    if isinstance(val, tuple):
        desc, refs = val
    else:
        desc, refs = val, None
    it['description'] = desc
    if refs:
        for k, v in refs.items():
            it[k] = v

if errors:
    raise SystemExit('\n'.join(errors))

with open(path_out, 'w', encoding='utf-8') as f:
    json.dump(data, f, ensure_ascii=False, indent=2)
    f.write('\n')
print('written', path_out)
